/**
 * n8n Code Node: Character Alignment to Word Timing Converter
 *
 * This script processes speech-to-text alignment data. It groups all characters
 * between space delimiters, calculates the total timing for that segment, and
 * then strips common punctuation from the start/end of the word text to deliver
 * a clean word with accurate timing.
 *
 * The output returns an array of objects, where each object contains only the
 * generated 'wordTimings' array for the corresponding input item.
 */

// Define characters that should be stripped from the START or END of a word segment.
// This handles punctuation like: .,:;!?()[]{} and the hyphen/apostrophe if they are at the edge.
const PUNCTUATION_TO_STRIP = new Set([
    '.', ',', ':', ';', '!', '?', '-', '\'', '"', '(', ')', '[', ']', '{', '}'
]);

// Helper function to determine if a character should be stripped from the word boundaries.
function isBoundaryPunctuation(char) {
    // Also strip the space character, though the main loop logic handles spaces as separators.
    return char === ' ' || PUNCTUATION_TO_STRIP.has(char);
}

// Stores the resulting objects for the output array
const resultItems = [];

// The main loop for the n8n Code node
for (const item of items) {
    // Check for the expected input path (based on the provided sample JSON)
    // Uses normalized_alignment first, falls back to alignment
    const alignment = item.json?.normalized_alignment || item.json?.alignment;

    if (!alignment || !alignment.characters || !alignment.character_start_times_seconds || !alignment.character_end_times_seconds) {
        console.warn('Skipping item due to missing alignment data.');
        // Still add an empty result for consistency if an item is skipped
        resultItems.push({ json: { wordTimings: [] } });
        continue;
    }

    const {
        characters,
        character_start_times_seconds,
        character_end_times_seconds
    } = alignment;

    const wordTimings = [];
    // Stores the sequence of characters (and their timings) between spaces
    let currentWordChars = [];

    for (let i = 0; i < characters.length; i++) {
        const char = characters[i];
        const charStartTime = character_start_times_seconds[i];
        const charEndTime = character_end_times_seconds[i];

        // A space acts as a segment boundary marker. When hit, process the accumulated segment.
        if (char === ' ') {
            if (currentWordChars.length > 0) {
                // Process the segment:

                // 1. Get the segment's full timing (from first char to last char)
                const start = currentWordChars[0].startTime;
                const end = currentWordChars[currentWordChars.length - 1].endTime;

                // 2. Determine the clean word boundaries by stripping boundary punctuation
                let wordEndIndex = currentWordChars.length - 1;
                while (wordEndIndex >= 0 && isBoundaryPunctuation(currentWordChars[wordEndIndex].char)) {
                    wordEndIndex--;
                }

                let wordStartIndex = 0;
                while (wordStartIndex < currentWordChars.length && isBoundaryPunctuation(currentWordChars[wordStartIndex].char)) {
                    wordStartIndex++;
                }

                // If a valid word body was found (e.g., segment wasn't just "...")
                if (wordStartIndex <= wordEndIndex) {
                    const wordSegment = currentWordChars.slice(wordStartIndex, wordEndIndex + 1);
                    const word = wordSegment.map(c => c.char).join('');

                    wordTimings.push({ word, start, end });
                }

                // Reset the accumulator for the next word
                currentWordChars = [];
            }
        } else {
            // Non-space character: accumulate it with its timing data
            currentWordChars.push({ 
                char: char, 
                startTime: charStartTime, 
                endTime: charEndTime 
            });
        }
    }

    // After the loop, process any final accumulated segment 
    if (currentWordChars.length > 0) {
        // 1. Get the segment's full timing
        const start = currentWordChars[0].startTime;
        const end = currentWordChars[currentWordChars.length - 1].endTime;

        // 2. Determine the clean word boundaries by stripping boundary punctuation
        let wordEndIndex = currentWordChars.length - 1;
        while (wordEndIndex >= 0 && isBoundaryPunctuation(currentWordChars[wordEndIndex].char)) {
            wordEndIndex--;
        }

        let wordStartIndex = 0;
        while (wordStartIndex < currentWordChars.length && isBoundaryPunctuation(currentWordChars[wordStartIndex].char)) {
            wordStartIndex++;
        }

        if (wordStartIndex <= wordEndIndex) {
            const wordSegment = currentWordChars.slice(wordStartIndex, wordEndIndex + 1);
            const word = wordSegment.map(c => c.char).join('');

            wordTimings.push({ word, start, end });
        }
    }

    // Create a new output item with only the wordTimings
    resultItems.push({
        json: {
            wordTimings: wordTimings
        }
    });
}

// Return the new array of result items, which only contain { wordTimings: [...] }
return resultItems;

